window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"CuSDv4Ftiow","speaker":"Subrahmanyam Jaishankar","role":"Minister for External Affairs","country":"India","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=CuSDv4Ftiow","date":"20260926","title":"🇮🇳 India - Minister for External Affairs Addresses UN General Debate, 81st Session | #UNGA","seconds":992,"words":1652,"counts":{"claims":31,"promises":1,"attacks":2},"topics":[{"topic":"UN multilateralism","share":0.2067,"seconds":205},{"topic":"AI governance","share":0.1398,"seconds":139},{"topic":"terrorism normalization","share":0.0836,"seconds":83},{"topic":"Israel-Gaza","share":0.0735,"seconds":73},{"topic":"Global South crisis","share":0.0721,"seconds":71},{"topic":"Maritime security","share":0.0687,"seconds":68},{"topic":"Global conflicts","share":0.0678,"seconds":67},{"topic":"Ukraine conflict","share":0.0678,"seconds":67},{"topic":"India development aid","share":0.0661,"seconds":66},{"topic":"multipolar world","share":0.0634,"seconds":63},{"topic":"India development projects","share":0.0626,"seconds":62},{"topic":"Peace process","share":0.0279,"seconds":28}],"timeline":[[6,72,"UN multilateralism"],[75,143,"Global conflicts"],[145,212,"Ukraine conflict"],[213,286,"Israel-Gaza"],[288,359,"Global South crisis"],[363,434,"AI governance"],[434,517,"terrorism normalization"],[518,580,"India development projects"],[582,647,"India development aid"],[649,726,"UN multilateralism"],[728,796,"Maritime security"],[797,865,"AI governance"],[866,929,"multipolar world"],[930,993,"UN multilateralism"],[994,1022,"Peace process"]],"stances":{"UN multilateralism":"Subrahmanyam Jaishankar states that the United Nations was founded to maintain international peace and security and take effective collective action.","Global conflicts":"Subrahmanyam Jaishankar states that global conflicts are undermining security, threatening progress, and penalizing countries far from the conflict zones.","Ukraine conflict":"India calls for restraint, de-escalation, and an end to the war while emphasizing the need to protect civilians and ensure energy security.","Israel-Gaza":"Subrahmanyam Jaishankar asserts that a durable peace requires a two-state solution and criticizes the weaponization of global issues.","Global South crisis":"Subrahmanyam Jaishankar states that the Global South faces an acute four F crisis involving food, fertilizer, finance, and security due to global competition and climate factors.","AI governance":"Subrahmanyam Jaishankar states that the misuse of artificial intelligence is sharpening bias and diluting mutual respect, creating anxiety rather than hope.","terrorism normalization":"India rejects the normalization of terrorism and asserts its right to self-defense while calling on perpetrators to change their behavior.","India development projects":"Subrahmanyam Jaishankar states that India's digital public infrastructure drives governance and socio-economic benefits, and that India is committed to sharing its replicable experiences with the global south through 600 major development projects in 78 nations.","India development aid":"India has provided infrastructure, climate action, and medical support to African nations and small island developing states through various initiatives.","Maritime security":"India condemns attacks on commercial shipping and seafarers, has joined an initiative with Liberia and 23 other partners to rally global opinion against such targeting, and emphasizes that scrupulously observing international law is integral to ensuring safety.","multipolar world":"Subrahmanyam Jaishankar states that the world is moving towards a multipolar order and that excluding large sections of humanity from this process is not feasible.","Peace process":"Subrahmanyam Jaishankar states that peace is the only path forward and there is no alternative way to achieve it."},"claims":[{"t":40,"quote":"from 1.4 billion people of Bharat","topic":"UN multilateralism","kind":"number"},{"t":50,"quote":"when the United Nations enters its ninth decade","topic":"UN multilateralism","kind":"fact"},{"t":94,"quote":"In a globalized world, the effects of war are felt Countries far from conflicts are being penalized for no fault of Those most impacted often have the least say.","topic":"Global conflicts","kind":"fact"},{"t":161,"quote":"the conflict in Ukraine, now in its fifth year, is equally concerning","topic":"Ukraine conflict","kind":"fact"},{"t":171,"quote":"Endless war must give way now to an end to war","topic":"Ukraine conflict","kind":"fact"},{"t":213,"quote":"We strongly believe that a durable and lasting peace requires a two-state solution.","topic":"Israel-Gaza","kind":"fact"},{"t":221,"quote":"In the meanwhile, India is contributing to humanitarian assistance and relief efforts for the Palestinian people.","topic":"Israel-Gaza","kind":"fact"},{"t":338,"quote":"It faces a four F crisis of the security of food, fertilizer, and finance.","topic":"Global South crisis","kind":"fact"},{"t":348,"quote":"The combined impact of a super El Nino compounding fertilizer shortages and now impediments to grain movements, all these are cause for alarm.","topic":"Global South crisis","kind":"fact"},{"t":376,"quote":"The march of technology that was meant to instill hope has now become a source of anxiety.","topic":"AI governance","kind":"fact"},{"t":383,"quote":"Misuse of AI is sharpening bias and diluting mutual respect.","topic":"AI governance","kind":"fact"},{"t":490,"quote":"its inclusive growth and all-round progress has advanced the prospects of 1/6 of","topic":"terrorism normalization","kind":"fact"},{"t":508,"quote":"this veritably lifts the global SDG","topic":"terrorism normalization","kind":"fact"},{"t":518,"quote":"Our digital public infrastructure is not only ensuring better governance, but is the backbone of delivering socio-economic benefits.","topic":"India development projects","kind":"fact"},{"t":529,"quote":"Rapid growth of infrastructure is visible across all its dimensions.","topic":"India development projects","kind":"fact"},{"t":575,"quote":"600 major Indian development projects in 78 nations testify to our commitment.","topic":"India development projects","kind":"number"},{"t":613,"quote":"African nations and small island developing states have been our preferred partners in this journey.","topic":"India development aid","kind":"fact"},{"t":620,"quote":"Initiatives like the International Solar the Coalition for Disaster Resilient or the Global Biofuels Alliance are all making steady progress.","topic":"India development aid","kind":"fact"},{"t":641,"quote":"India has sent medical shipments to conflict zones, epidemic locations, and after natural disasters.","topic":"India development aid","kind":"fact"},{"t":657,"quote":"Our limb fitment camps have given a new hope to many across the world.","topic":"UN multilateralism","kind":"fact"},{"t":701,"quote":"Right now, our contingents are present in nine out of 11 mandates.","topic":"UN multilateralism","kind":"number"},{"t":714,"quote":"We take pride that an Indian woman combat helicopter pilot was awarded the UN 2025 military gender advocate of the year.","topic":"UN multilateralism","kind":"fact"},{"t":737,"quote":"There have been attacks on commercial shipping and seafarers in the Gulf and from the Red Sea to the Black Sea.","topic":"Maritime security","kind":"fact"},{"t":744,"quote":"Indian seafarers have lost their lives, as indeed have others from other nations.","topic":"Maritime security","kind":"fact"},{"t":755,"quote":"India has joined Liberia and 23 other partners in an initiative to rally global public opinion against such unwarranted targeting.","topic":"Maritime security","kind":"fact"},{"t":797,"quote":"We view AI as a transformational driver for human empowerment, economic prosperity, and population scale","topic":"AI governance","kind":"fact"},{"t":866,"quote":"Economic rebalancing is well underway. The political one is also visible. And the third facet, cultural rebalancing, must now be taken forward.","topic":"multipolar world","kind":"fact"},{"t":878,"quote":"Mr. President, we are now well on our way towards a multipolar world. The post-1945 order is giving way to new realities.","topic":"multipolar world","kind":"fact"},{"t":939,"quote":"after a decade of service and dedication to the cause of multilateralism, we will soon bid farewell to Secretary General Antonio Guterres.","topic":"UN multilateralism","kind":"fact"},{"t":950,"quote":"India deeply values his many contributions, in particular, his personal support for Mission Life.","topic":"UN multilateralism","kind":"fact"},{"t":996,"quote":"there is no way to peace. Peace is the way.","topic":"Peace process","kind":"fact"}],"promises":[{"t":193,"quote":"India is prepared to do everything to ameliorate the situation, especially with regard to food and energy security","topic":"Ukraine conflict","kind":"promise"}],"attacks":[{"t":136,"quote":"The targeting of commercial shipping and transiting international waterways is simply unacceptable.","topic":"Global conflicts","target":"Unnamed opponents"},{"t":437,"quote":"a serial practitioner of terrorism misrepresented facts before this Arguments were invoked to normalize terrorism and claim immunity from its That will not stand.","topic":"terrorism normalization","target":"Unnamed opponents"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":6,"topic":"UN multilateralism","text":"give the floor to His Excellency Subrahmanyam Jaishankar, Minister of External Affairs of India. &gt;&gt; Mr. President, ladies and gentlemen, from 1.4 billion people of Bharat. We are gathered at this General Assembly when the United Nations enters its ninth decade. It was founded to maintain international peace and security and take effective collective action to that end. committed to develop friendly relations and to strengthen universal peace."},{"t":75,"topic":"Global conflicts","text":"even as we meet, conflicts and confrontations remain our primary preoccupation. The inability to maintain peace is not just undermining security, but threatening progress and retarding development. In a globalized world, the effects of war are felt Countries far from conflicts are being penalized for no fault of Those most impacted often have the least say. This Assembly must face up to true state of affairs. This year we are witnessing a conflict in the one that is exacerbating an already difficult situation. We remain deeply concerned over continuing hostilities. The targeting of commercial shipping and transiting international waterways is simply unacceptable."},{"t":145,"topic":"Ukraine conflict","text":"India calls upon all parties to exercise restraint, de-escalate ensure protection of civilians and uninterrupted flow of energy and Mr. President, the conflict in Ukraine, now in its fifth year, is equally concerning. As Prime Minister Narendra Modi stated, \"Endless war must give way now to an end to war.\" India supports ongoing initiatives to bring peace. Even as this is underway, there is an urgent need to address the security of seafarers and supply of food grains and energy. India is prepared to do everything to ameliorate the situation, especially with regard to food and energy security. Tensions and violence also regrettably continue in West Asia or the Middle East."},{"t":213,"topic":"Israel-Gaza","text":"We strongly believe that a durable and lasting peace requires a two-state solution. In the meanwhile, India is contributing to humanitarian assistance and relief efforts for the Palestinian people. Mr. President, let us recognize that peace is not just the absence of war. If the world is subjected to continuous threats and pressures, then we are really living on the edge of an abyss. All it takes is one more step to push us over. it is imperative to strengthen security, and predictability. These are crucial elements of the enabling environment for peace. If any of them are undermined, will inevitably be weakened. &gt;&gt; After eight decades of the UN, this should have become our second what we are actually seeing is a weaponization of everything."},{"t":288,"topic":"Global South crisis","text":"A mindset of extreme competition has set undermining institutions and establishing choke points. It extends from the world of finance to constricting market access, disrupting supply chains, and withholding technology. Resources and connectivity have become particularly subject to As a result, nations are now more focused on de-risking and diversifying. Now, while this may secure their interest to varying degrees, the overall atmosphere is no longer that of trust or goodwill. Mr. President, the predicament of the global South is particularly acute. It faces a four F crisis of the security of food, fertilizer, and finance. The combined impact of a super El Nino compounding fertilizer shortages and now impediments to grain movements, all these are cause for alarm."},{"t":363,"topic":"AI governance","text":"SDG progress is under increasing The global south's right to industrialize is also undermined by non-market practices and market The march of technology that was meant to instill hope has now become a source of anxiety. Misuse of AI is sharpening bias and diluting mutual respect. These directions bode ill for the aims and objectives of the United Nations. A persistent threat to peace has been the scourge of terrorism. That this could be state-sponsored with cross-border purpose makes it a direct affront to the global Governments indulging in such practices must be held accountable. There must be no dilution in our zero-tolerance approach towards Its financial aspects, in particular, should be exposed and should be Mr."},{"t":434,"topic":"terrorism normalization","text":"President, a serial practitioner of terrorism misrepresented facts before this Arguments were invoked to normalize terrorism and claim immunity from its That will not stand. Our right to defend ourselves against terrorism will be exercised. Mr. President, friendship and goodwill cannot coexist with terrorism. And understandings premised on that will naturally be called into question. It is for the perpetrator of terrorism to mend its ways. Mr. President, given the state of the world, each member of the UN must ask themselves what they can do. In so far as India is concerned, its inclusive growth and all-round progress has advanced the prospects of 1/6 of When health, nutrition, and education are effectively delivered, when drinking water, electricity, roads, and housing are ensured, this veritably lifts the global SDG But today, India has much more than that to offer."},{"t":518,"topic":"India development projects","text":"Our digital public infrastructure is not only ensuring better governance, but is the backbone of delivering socio-economic benefits. Rapid growth of infrastructure is visible across all its dimensions. A continuously improving ease of doing business, ease of living, startup and innovation culture, and focused sectoral missions have all contributed to our economic story. Even as India progresses, we are conscious of our global We know that many of our experiences and achievements are replicable elsewhere. The deep solidarity of the global south has always encouraged us to share what we have. we respond more actively to the requirements of our partners. 600 major Indian development projects in 78 nations testify to our commitment."},{"t":582,"topic":"India development aid","text":"A commitment that ranges from infrastructure, manufacturing, and agriculture to IT and to capacity building. Climate action projects and initiatives have been an important part of these Whether it is clean energy and clean water projects, sustainable agriculture, or the dissemination of best practices and technology, our capabilities and experiences have been reflected abroad. African nations and small island developing states have been our preferred partners in this journey. Initiatives like the International Solar the Coalition for Disaster Resilient or the Global Biofuels Alliance are all making steady progress. Mr. President, the turbulence of our times also demands more from each of us. India has sent medical shipments to conflict zones, epidemic locations, and after natural disasters."},{"t":649,"topic":"UN multilateralism","text":"As a first responder, we were there early, be it the Nepal flash floods or the Venezuela earthquake. Our limb fitment camps have given a new hope to many across the world. Whether to meet food and medicine energy or fertilizer needs, or indeed creating livelihoods, India has contributed continuously and will do Our capacity building and experience sharing programs have made a real difference across the global south, especially in Africa. The same international spirit also inspires our contribution to safeguarding peace. has always been at the forefront of UN peacekeeping operations. Right now, our contingents are present in nine out of 11 mandates. Our troops have stood their ground firmly and professionally even under We take pride that an Indian woman combat helicopter pilot was awarded the UN 2025 military gender advocate of the year."},{"t":728,"topic":"Maritime security","text":"Mr. President, new challenges in the maritime domain have added to long-standing ones on There have been attacks on commercial shipping and seafarers in the Gulf and from the Red Sea to the Black Sea. Indian seafarers have lost their lives, as indeed have others from other nations. This is completely unacceptable. India has joined Liberia and 23 other partners in an initiative to rally global public opinion against such unwarranted targeting. We must ensure that the safety and security of shipping and seafarers is never compromised. Scrupulously observing international law is an integral element of that endeavor. An issue central to current global conversations is that of AI. India hosted the AI Impact Summit this Gathering together the best minds on that subject."},{"t":797,"topic":"AI governance","text":"We view AI as a transformational driver for human empowerment, economic prosperity, and population scale We believe in the right of each nation to shape its ecosystem within the with the development of its own models and deployment strategies consistent with its national goals and priorities. AI will be very much part of our partnership agenda with the global As technology is democratized, this process is greatly facilitated, Mr. President, by an ethos of mutual Indeed, care and consideration for the interests and viewpoints of others reinforces even the prospects of peace. And that attitude is best fostered by an appreciation of each other's culture, heritage, and traditions. In a globalized world, we must continuously and vigorously promote international understanding."},{"t":866,"topic":"multipolar world","text":"Economic rebalancing is well underway. The political one is also visible. And the third facet, cultural rebalancing, must now be taken forward. Mr. President, we are now well on our way towards a multipolar world. The post-1945 order is giving way to new realities. This process of adjustment, accommodation, and acceptance will not be easy. Much of the turbulence that we witness emanates from those very difficulties. the march of an intrinsically diverse world towards a more democratic future cannot be halted. Peace in a pluralistic order requires civil conversations. It requires broad-based consultations. It requires transparent decision-making. Large sections of humanity cannot be excluded from that process."},{"t":930,"topic":"UN multilateralism","text":"The case for reformed multilateralism only gets stronger day after day. Mr. President, after a decade of service and dedication to the cause of multilateralism, we will soon bid farewell to Secretary General Antonio Guterres. India deeply values his many contributions, in particular, his personal support for Mission Life. Mr. President, at the conclusion of this general we hope that all participating delegations leave with a greater commitment to peace, to development, and to prosperity. This cannot be an imposition or even a negotiation. It must be a mindset. It must be an outlook. It must be a belief. In the lawns outside this building are recorded the powerful words of Mahatma Gandhi, and that should serve as an inspiration for these times."},{"t":994,"topic":"Peace process","text":"And those words are that there is no way to peace. Peace is the way. I thank you. &gt;&gt; I thank the Minister of External Affairs of India for his contribution."}],"compare":[{"topic":"UN & its reform","share":0.2067,"mean":0.2047,"rank":87,"others":170},{"topic":"Artificial Intelligence","share":0.1398,"mean":0.05,"rank":21,"others":83},{"topic":"International Law & Order","share":0.1312,"mean":0.06,"rank":31,"others":102},{"topic":"Terrorism","share":0.0836,"mean":0.0025,"rank":4,"others":6},{"topic":"Israel–Palestine","share":0.0735,"mean":0.0523,"rank":50,"others":76},{"topic":"Global Economy","share":0.0721,"mean":0.0142,"rank":17,"others":31},{"topic":"Maritime Security","share":0.0687,"mean":0.0044,"rank":6,"others":9},{"topic":"Russia-Ukraine War","share":0.0678,"mean":0.0351,"rank":37,"others":44}]};
